LIMIT 1

SELECT uc.id, uc.user_id, uc.target_type, uc.target_id, uc.create_time, -- 对象名称 COALESCE( tr.name, -- 旅游线路 ess.name, -- 养老驿站 stp.plan_name, -- 研学方案 sta.activity_name, -- 研学活动 vh.homestay_name, -- 民宿 spu.title, -- 农产品 r.name -- 餐饮 ) AS target_name, -- 收藏总数（子查询） (SELECT COUNT(*) FROM user_collect uc2 WHERE uc2.target_type = uc.target_type AND uc2.target_id = uc.target_id) AS collect_count, -- 当前用户是否收藏（如果查询的是某个用户的收藏列表，则都是true；否则根据currentUserId判断）
-- 查询的是某个用户的收藏列表，列表中的记录都是该用户收藏的 1 AS is_collected
-- 查询所有收藏记录，根据currentUserId判断是否收藏 CASE WHEN EXISTS ( SELECT 1 FROM user_collect uc3 WHERE uc3.user_id = #{currentUserId} AND uc3.target_type = uc.target_type AND uc3.target_id = uc.target_id ) THEN 1 ELSE 0 END AS is_collected
-- 没有传currentUserId，返回null NULL AS is_collected
FROM user_collect uc LEFT JOIN tour_route tr ON uc.target_type = 'tour_route' AND CAST(uc.target_id AS UNSIGNED) = tr.id LEFT JOIN elderly_service_subject ess ON uc.target_type = 'elderly_station' AND CAST(uc.target_id AS UNSIGNED) = ess.id LEFT JOIN study_tour_plan stp ON uc.target_type = 'study_plan' AND CAST(uc.target_id AS UNSIGNED) = stp.id LEFT JOIN study_tour_activity sta ON uc.target_type = 'study_activity' AND CAST(uc.target_id AS UNSIGNED) = sta.id LEFT JOIN village_homestay vh ON uc.target_type = 'homestay' AND CAST(uc.target_id AS UNSIGNED) = vh.id LEFT JOIN spu ON uc.target_type = 'product' AND CAST(uc.target_id AS UNSIGNED) = spu.id LEFT JOIN restaurant r ON uc.target_type = 'restaurant' AND CAST(uc.target_id AS UNSIGNED) = r.id
AND uc.user_id = #{userId}
AND uc.target_type = #{targetType}
ORDER BY uc.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM user_collect


        AND user_id = #{userId}


        AND target_type = #{targetType}

SELECT COUNT(*) FROM user_collect
WHERE target_type = #{targetType}
  AND target_id = #{targetId}

SELECT COUNT(DISTINCT CONCAT(target_type, '_', target_id)) FROM user_collect
AND target_type = #{targetType}
AND create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
